export const PARTY=['warrior','cleric','mage','thief','champion','scroll'];
export const DUNGEON=['goblin','skeleton','slime','chest','potion','dragon'];
export const MONSTERS=['goblin','skeleton','slime'];
export const NAMES={warrior:'Воин',cleric:'Клирик',mage:'Маг',thief:'Вор',champion:'Страж',scroll:'Свиток',goblin:'Гоблин',skeleton:'Скелет',slime:'Слизень',chest:'Сундук',potion:'Зелье',dragon:'Дракон',sword:'Разящий меч',talisman:'Талисман',wand:'Жезл силы',tools:'Воровские инструменты',ring:'Кольцо невидимости',scale:'Драконья чешуйка',elixir:'Эликсир',bait:'Приманка для дракона',portal:'Городской портал'};
export const ITEM_COUNTS={sword:3,talisman:3,wand:3,tools:3,scroll:3,ring:4,scale:6,elixir:3,bait:4,portal:4};
export const SUBSTITUTE={sword:'warrior',talisman:'cleric',wand:'mage',tools:'thief',scroll:'scroll'};
const SPECIALTY={warrior:'goblin',cleric:'skeleton',mage:'slime'};
function requireOk(value,message){if(!value)throw new Error(message);}
function random(s,max){let t=s.seed+=0x6D2B79F5;t=Math.imul(t^t>>>15,t|1);t^=t+Math.imul(t^t>>>7,t|61);s.seed=s.seed>>>0;return Math.floor(((t^t>>>14)>>>0)/4294967296*max);}
function note(s,text){s.log.push(text);}
export function current(s){return s.players[s.turn%s.players.length];}
export function score(p){return p.xp+p.items.reduce((n,x)=>n+(x.kind==='portal'?2:1),0)+Math.floor(p.items.filter(x=>x.kind==='scale').length/2)*2;}
export function createGame(names,seed,adventures=3){requireOk(Array.isArray(names)&&names.length>=1&&names.length<=6&&names.every(x=>typeof x==='string'&&x.trim().length>0&&x.length<=30),'Укажите от 1 до 6 имён, не длиннее 30 символов.');requireOk(Number.isInteger(adventures)&&adventures>=1&&adventures<=10,'Выберите от 1 до 10 приключений.');return {version:1,adventures,seed:seed>>>0,players:names.map(name=>({name:name.trim(),xp:0,items:[],completed:0})),turn:0,phase:'ready',level:0,party:[],dungeon:[],lair:[],pool:Object.entries(ITEM_COUNTS).flatMap(([kind,n])=>Array.from({length:n},(_,i)=>({id:kind+'-'+i,kind}))),log:[],last:null};}
function reward(s){if(s.pool.length){const [item]=s.pool.splice(random(s,s.pool.length),1);current(s).items.push(item);note(s,'Сокровище: '+NAMES[item.kind]+'.');}else{current(s).xp++;note(s,'Сундук сокровищ пуст: +1 опыт.');}}
function populate(s){s.dungeon=[];const available=Array.from({length:7},(_,i)=>i).filter(id=>!s.lair.includes(id));available.slice(0,Math.min(s.level,available.length)).forEach(id=>{const face=DUNGEON[random(s,6)];if(face==='dragon')s.lair.push(id);else s.dungeon.push({id,face});});s.phase='battle';note(s,'Уровень '+s.level+': '+(s.dungeon.map(x=>NAMES[x.face]).join(', ')||'все кубики в логове')+'. Драконов в логове: '+s.lair.length+'.');}
function source(s,ref){requireOk(ref&&['die','item'].includes(ref.type),'Выберите кубик или сокровище.');if(ref.type==='die'){const die=s.party.find(x=>x.id===ref.id&&x.zone==='active');requireOk(die,'Этот кубик недоступен.');return {face:die.face,die};}const item=current(s).items.find(x=>x.id===ref.id);requireOk(item,'Сокровище недоступно.');requireOk(SUBSTITUTE[item.kind],'Это сокровище нельзя использовать как сопартийца.');return {face:SUBSTITUTE[item.kind],item};}
function spend(s,ref){const x=source(s,ref);if(x.die)x.die.zone='grave';else consumeItem(s,x.item.id);return x.face;}
function consumeItem(s,id){const p=current(s),i=p.items.findIndex(x=>x.id===id);requireOk(i>=0,'Сокровище недоступно.');const [item]=p.items.splice(i,1);s.pool.push(item);return item;}
function targets(s,ids,allowed){requireOk(Array.isArray(ids)&&ids.length>0&&new Set(ids).size===ids.length,'Выберите цели.');const result=ids.map(id=>s.dungeon.find(x=>x.id===id));requireOk(result.every(x=>x&&allowed.includes(x.face)),'Недопустимые цели.');return result;}
function removeTargets(s,ids){s.dungeon=s.dungeon.filter(x=>!ids.includes(x.id));}
function revive(s,faces){requireOk(Array.isArray(faces)&&faces.every(x=>PARTY.includes(x)),'Выберите грани возвращаемых кубиков.');const grave=s.party.filter(x=>x.zone==='grave');requireOk(faces.length<=grave.length,'На кладбище недостаточно кубиков.');faces.forEach((face,i)=>{grave[i].zone='active';grave[i].face=face;});}
function finish(s,reason,earned){const p=current(s),adventures=s.adventures||3;p.xp+=earned;p.completed++;s.last={name:p.name,reason,earned,level:s.level};s.dungeon=[];s.lair=[];note(s,p.name+': '+reason+'. Опыт за глубину: +'+earned+'.');s.turn++;s.phase=s.turn===s.players.length*adventures?'finished':'end';}
export function act(original,a){const s=structuredClone(original);requireOk(a&&typeof a.type==='string','Неизвестное действие.');const playing=['battle','loot','dragon','regroup'].includes(s.phase);
 switch(a.type){
 case 'begin': requireOk(['ready','end'].includes(s.phase),'Приключение уже началось.');s.party=Array.from({length:7},(_,id)=>({id,face:PARTY[random(s,6)],zone:'active'}));s.level=1;s.lair=[];note(s,'— '+current(s).name+', приключение '+(current(s).completed+1)+' из '+(s.adventures||3)+' —');populate(s);break;
 case 'attack':{requireOk(s.phase==='battle','Сейчас не фаза монстров.');const f=source(s,a.source).face;requireOk(f!=='scroll','Свиток не сражается.');const ts=targets(s,a.targets,MONSTERS);requireOk(ts.every(x=>x.face===ts[0].face),'За одну атаку выберите монстров одного типа.');requireOk(ts.length===1||f==='champion'||SPECIALTY[f]===ts[0].face,'Этот сопартиец побеждает только одного такого монстра.');spend(s,a.source);removeTargets(s,a.targets);note(s,NAMES[f]+' побеждает: '+NAMES[ts[0].face]+' × '+ts.length+'.');break;}
 case 'reroll':{requireOk(s.phase==='battle','Свитки применяются в фазе монстров.');requireOk(source(s,a.source).face==='scroll','Для переброса нужен свиток.');requireOk(Array.isArray(a.party)&&Array.isArray(a.dungeon)&&new Set(a.party).size===a.party.length&&new Set(a.dungeon).size===a.dungeon.length,'Некорректные цели переброса.');requireOk(a.party.length+a.dungeon.length>0,'Выберите кубики для переброса.');const dice=a.party.map(id=>s.party.find(x=>x.id===id&&x.zone==='active'));requireOk(dice.every(Boolean),'Можно перебросить только доступные кубики.');requireOk(a.source.type!=='die'||!a.party.includes(a.source.id),'Нельзя перебросить потраченный свиток.');const ds=a.dungeon.map(id=>s.dungeon.find(x=>x.id===id));requireOk(ds.every(Boolean),'Кубики из логова недоступны.');spend(s,a.source);dice.forEach(x=>x.face=PARTY[random(s,6)]);ds.forEach(x=>{x.face=DUNGEON[random(s,6)];if(x.face==='dragon')s.lair.push(x.id);});s.dungeon=s.dungeon.filter(x=>x.face!=='dragon');note(s,'Свиток: переброшено кубиков — '+(dice.length+ds.length)+'.');break;}
 case 'advance': if(s.phase==='battle'){requireOk(!s.dungeon.some(x=>MONSTERS.includes(x.face)),'Сначала победите всех монстров.');s.phase='loot';note(s,'Фаза добычи.');}else if(s.phase==='loot'){s.dungeon=[];s.phase=s.lair.length>=3?'dragon':'regroup';note(s,s.phase==='dragon'?'Дракон проснулся! Нужны три разных сопартийца.':'Перегруппировка: продолжить или вернуться в таверну.');}else throw new Error('Нельзя перейти к следующей фазе.');break;
 case 'open':{requireOk(s.phase==='loot','Сундуки открываются в фазе добычи.');const f=source(s,a.source).face;requireOk(f!=='scroll','Свиток не открывает сундуки.');const ts=targets(s,a.targets,['chest']);requireOk(ts.length===1||['thief','champion'].includes(f),'Этот сопартиец открывает только один сундук.');spend(s,a.source);removeTargets(s,a.targets);note(s,'Открыто сундуков: '+ts.length+'.');ts.forEach(()=>reward(s));break;}
 case 'drink':{requireOk(s.phase==='loot','Зелья пьют в фазе добычи.');const ts=targets(s,a.targets,['potion']);spend(s,a.source);const n=Math.min(ts.length,s.party.filter(x=>x.zone==='grave').length);requireOk(a.faces?.length===n,'Выберите грань для каждого возвращаемого кубика ('+n+').');revive(s,a.faces);removeTargets(s,a.targets);note(s,'Выпито зелий: '+ts.length+'. Возвращено сопартийцев: '+n+'.');break;}
 case 'slay':{requireOk(s.phase==='dragon'&&s.lair.length>=3,'Сейчас нет боя с драконом.');requireOk(Array.isArray(a.sources)&&a.sources.length===3,'Нужны три разных типа сопартийцев.');requireOk(new Set(a.sources.map(x=>x.type+':'+x.id)).size===3,'Нельзя использовать один источник дважды.');const fs=a.sources.map(x=>source(s,x).face);requireOk(!fs.includes('scroll')&&new Set(fs).size===3,'Нужны три разных типа сопартийцев, без свитков.');a.sources.forEach(x=>spend(s,x));s.lair=[];current(s).xp++;note(s,'Дракон побеждён! +1 опыт и сокровище.');reward(s);s.phase='regroup';break;}
 case 'item':{requireOk(playing,'Сокровища доступны во время приключения.');const item=current(s).items.find(x=>x.id===a.id);requireOk(item,'Сокровище недоступно.');requireOk(['ring','elixir','bait','portal'].includes(item.kind),'Это сокровище применяется иначе.');if(item.kind==='ring'){requireOk(s.lair.length>0,'Логово уже пусто.');consumeItem(s,a.id);s.lair=[];note(s,'Кольцо невидимости: логово очищено без награды.');if(s.phase==='dragon')s.phase='regroup';}if(item.kind==='elixir'){requireOk(s.party.some(x=>x.zone==='grave'),'Кладбище пусто.');requireOk(a.faces?.length===1,'Выберите одну грань.');consumeItem(s,a.id);revive(s,a.faces);note(s,'Эликсир возвращает: '+NAMES[a.faces[0]]+'.');}if(item.kind==='bait'){requireOk(s.dungeon.length>0,'На уровне нет кубиков для превращения.');consumeItem(s,a.id);s.lair.push(...s.dungeon.map(x=>x.id));s.dungeon=[];note(s,'Приманка: все кубики уровня перемещены в логово.');}if(item.kind==='portal'){consumeItem(s,a.id);finish(s,'городской портал',s.level);}break;}
 case 'descend':requireOk(s.phase==='regroup'&&s.level<10,'Спуск недоступен.');s.level++;populate(s);break;
 case 'rest':requireOk(s.phase==='regroup','Сначала завершите уровень.');finish(s,s.level===10?'подземелье покорено':'отдых в таверне',s.level);break;
 case 'flee':requireOk(['battle','dragon'].includes(s.phase),'Сейчас нельзя бежать.');finish(s,'бегство',0);break;
 default:throw new Error('Неизвестное действие.');
 }
 assertState(s);return s;
}
export function assertState(s){requireOk(s.party.length===0||s.party.length===7,'Нарушено количество кубиков партии.');requireOk(s.dungeon.length+s.lair.length<=7&&new Set([...s.dungeon.map(x=>x.id),...s.lair]).size===s.dungeon.length+s.lair.length,'Нарушено количество кубиков подземелья.');const items=[...s.pool,...s.players.flatMap(p=>p.items)],adventures=s.adventures||3;requireOk(Number.isInteger(adventures)&&adventures>=1&&adventures<=10,'Неверное число приключений.');requireOk(items.length===36&&new Set(items.map(x=>x.id)).size===36,'Нарушен состав сокровищ.');requireOk(s.players.every(p=>p.xp>=0&&p.completed<=adventures),'Неверные очки или число приключений.');}
export function standings(s){return s.players.map(p=>({...p,total:score(p)})).sort((a,b)=>b.total-a.total||a.items.length-b.items.length);}
